 base_time:{label:'增益持续时间',kind:'seconds'},
 base_damage_scale:{label:'伤害倍率',kind:'pctMult'},
 base_ex_damage_scale:{label:'对寒冷、冻结目标的伤害倍率',kind:'pctMult'},
