  if(src.id==='char_391_rosmon'&&src.rosmonPartner!=null)auras.push({key:'rosmon-caster',stat:'atk',layer:'maxSame',v:.08,src:'迷迭香·感知稳定',ok:v=>v.uid===src.rosmonPartner});
